import{_ as t,J as r,b as n,e as o,a8 as i,f as s,L as c}from"./chunks/framework.BXWQBDlf.js";const f=JSON.parse('{"title":"GR32_Paths","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_Paths","entity":"GR32_Paths","kind":"Unit","summary":"Provides vector path construction, curve flattening algorithms, and vector canvas drawing engine for Graphics32.","title":"GR32_Paths","date":1789219214000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_Paths/index.md","filePath":"api/GR32_Paths/index.md","lastUpdated":1789219214000,"timestamp":1789219214000,"datetime":"2026-09-12T13:20:14.000Z"}'),l={name:"api/GR32_Paths/index.md"};function d(p,e,h,u,m,g){const a=r("ApiMembers");return n(),o("div",null,[e[0]||(e[0]=i('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_Paths</code> unit defines the core 2D vector graphics path building and canvas rendering framework in Graphics32. It provides a flexible hierarchy of classes for creating, flattening, and rasterizing complex vector shapes, curves, and text outlines onto bitmap pixel buffers.</p><p>Key components in <code>GR32_Paths</code> include:</p><ul><li><strong>Path Construction Base Class</strong>: <a href="/api/GR32_Paths/TCustomPath/">TCustomPath</a> provides high-level vector drawing directives including absolute and relative line movements, cubic Bezier curves (<code>CurveTo</code>), quadratic/conic Bezier curves (<code>ConicTo</code>), arcs, rectangles, rounded rectangles, ellipses, circles, polylines, and polygons.</li><li><strong>Curve Flattening Engine</strong>: <a href="/api/GR32_Paths/TFlattenedPath/">TFlattenedPath</a> automatically tessellates mathematical curves into discrete polygonal vertex contours (<code>TArrayOfArrayOfFloatPoint</code>), governed by configurable error tolerances (<code>CBezierTolerance</code>, <code>QBezierTolerance</code>).</li><li><strong>Canvas Abstraction</strong>: <a href="/api/GR32_Paths/TCustomCanvas/">TCustomCanvas</a> extends path flattening with coordinate transformation capabilities (<a href="/api/GR32_Transforms/TTransformation/">TTransformation</a>).</li><li><strong>2D Vector Canvas</strong>: <a href="/api/GR32_Paths/TCanvas32/">TCanvas32</a> integrates path building with bitmap rendering targets (<a href="/api/GR32/TBitmap32/">TBitmap32</a>), customizable stroke and fill brushes (<a href="/api/GR32_Brushes/TBrushCollection/">TBrushCollection</a>), anti-aliased polygon rasterizers (<a href="/api/GR32_Polygons/TPolygonRenderer32/">TPolygonRenderer32</a>), and vector font text outline rendering (<code>RenderText</code>, <code>MeasureText</code>).</li></ul>',4)),s("p",null,[c(a,{type:"members"})])])}const T=t(l,[["render",d]]);export{f as __pageData,T as default};
